window.CHUJI_DATA_12 = [{"l": 411, "lt": "Lesson 111 Confucius 孔子", "i": 1, "type": "reading", "en": "Confucius is respected by most Chinese as the greatest teacher of all time.", "zh": "孔子被许许多多中国人尊为自古以来最伟大的老师。", "audio": "chuji_l111_01.mp3", "localAudio": "audio_chunks/chuji_l111_01.mp3", "b64": "", "src": "chuji"}, {"l": 411, "lt": "Lesson 111 Confucius 孔子", "i": 2, "type": "reading", "en": "Perhaps the most important word he taught was \"ren,\" which means \"benevolence.\"", "zh": "或许他所传授的最重要的一个字就是“仁”，也就是英文的“benevolence”。", "audio": "chuji_l111_02.mp3", "localAudio": "audio_chunks/chuji_l111_02.mp3", "b64": "", "src": "chuji"}, {"l": 411, "lt": "Lesson 111 Confucius 孔子", "i": 3, "type": "reading", "en": "According to Confucius, benevolence means courtesy, loyalty and unselfishness.", "zh": "根据孔子的说法，仁的意思就是礼貌、忠贞以及无私。", "audio": "chuji_l111_03.mp3", "localAudio": "audio_chunks/chuji_l111_03.mp3", "b64": "", "src": "chuji"}, {"l": 411, "lt": "Lesson 111 Confucius 孔子", "i": 4, "type": "reading", "en": "In fact, benevolence is the essence of his teachings.", "zh": "事实上，仁是他教义的精髓。", "audio": "chuji_l111_04.mp3", "localAudio": "audio_chunks/chuji_l111_04.mp3", "b64": "", "src": "chuji"}, {"l": 411, "lt": "Lesson 111 Confucius 孔子", "i": 5, "type": "reading", "en": "Every teacher should, therefore, follow in his footsteps and emphasize benevolence when teaching.", "zh": "因此，每个老师在教学时，应效法孔子并强调仁的道理。", "audio": "chuji_l111_05.mp3", "localAudio": "audio_chunks/chuji_l111_05.mp3", "b64": "", "src": "chuji"}, {"l": 412, "lt": "Lesson 112 It's My Pleasure 不客气", "i": 1, "type": "dialog", "en": "Excuse me. Would you like to sit down?", "zh": "对不起。您要坐吗？", "audio": "chuji_l112_01.mp3", "localAudio": "audio_chunks/chuji_l112_01.mp3", "b64": "", "src": "chuji", "speaker": "Man", "note": "说话人: Man"}, {"l": 412, "lt": "Lesson 112 It's My Pleasure 不客气", "i": 2, "type": "dialog", "en": "That's very nice of you. Thank you.", "zh": "你人真好。谢谢你。", "audio": "chuji_l112_02.mp3", "localAudio": "audio_chunks/chuji_l112_02.mp3", "b64": "", "src": "chuji", "speaker": "Old Lady", "note": "说话人: Old Lady"}, {"l": 412, "lt": "Lesson 112 It's My Pleasure 不客气", "i": 3, "type": "dialog", "en": "It's my pleasure.", "zh": "不客气。", "audio": "chuji_l112_03.mp3", "localAudio": "audio_chunks/chuji_l112_03.mp3", "b64": "", "src": "chuji", "speaker": "Man", "note": "说话人: Man"}, {"l": 412, "lt": "Lesson 112 It's My Pleasure 不客气", "i": 4, "type": "dialog", "en": "You're a very courteous gentleman.", "zh": "你真是一位有礼貌的绅士。", "audio": "chuji_l112_04.mp3", "localAudio": "audio_chunks/chuji_l112_04.mp3", "b64": "", "src": "chuji", "speaker": "Old Lady", "note": "说话人: Old Lady"}, {"l": 412, "lt": "Lesson 112 It's My Pleasure 不客气", "i": 5, "type": "dialog", "en": "Thank you.", "zh": "谢谢您。", "audio": "chuji_l112_05.mp3", "localAudio": "audio_chunks/chuji_l112_05.mp3", "b64": "", "src": "chuji", "speaker": "Man", "note": "说话人: Man"}, {"l": 413, "lt": "Lesson 113 Something Well Begun Is Half Done 好的开始是成功的一半", "i": 1, "type": "reading", "en": "Work is a very important part of life.", "zh": "工作是人生非常重要的一部分。", "audio": "chuji_l113_01.mp3", "localAudio": "audio_chunks/chuji_l113_01.mp3", "b64": "", "src": "chuji"}, {"l": 413, "lt": "Lesson 113 Something Well Begun Is Half Done 好的开始是成功的一半", "i": 2, "type": "reading", "en": "People work in order to earn a living.", "zh": "人们工作是为了要谋生。", "audio": "chuji_l113_02.mp3", "localAudio": "audio_chunks/chuji_l113_02.mp3", "b64": "", "src": "chuji"}, {"l": 413, "lt": "Lesson 113 Something Well Begun Is Half Done 好的开始是成功的一半", "i": 3, "type": "reading", "en": "A country can only make progress if its people work.", "zh": "一个国家唯有其人民工作才能获致进步。", "audio": "chuji_l113_03.mp3", "localAudio": "audio_chunks/chuji_l113_03.mp3", "b64": "", "src": "chuji"}, {"l": 413, "lt": "Lesson 113 Something Well Begun Is Half Done 好的开始是成功的一半", "i": 4, "type": "reading", "en": "It is, therefore, important for us to be hardworking.", "zh": "因此，我们必须要勤奋工作是很重要的。", "audio": "chuji_l113_04.mp3", "localAudio": "audio_chunks/chuji_l113_04.mp3", "b64": "", "src": "chuji"}, {"l": 413, "lt": "Lesson 113 Something Well Begun Is Half Done 好的开始是成功的一半", "i": 5, "type": "reading", "en": "When we work, there is one golden rule we should always remember: Something well begun is half done.", "zh": "当我们工作时，有一项黄金法则我们应当永远记住：好的开始是成功的一半。", "audio": "chuji_l113_05.mp3", "localAudio": "audio_chunks/chuji_l113_05.mp3", "b64": "", "src": "chuji"}, {"l": 414, "lt": "Lesson 114 No Pain, No Gain 一分耕耘，一分收获", "i": 1, "type": "dialog", "en": "What does John do for a living?", "zh": "约翰是靠什么谋生的？", "audio": "chuji_l114_01.mp3", "localAudio": "audio_chunks/chuji_l114_01.mp3", "b64": "", "src": "chuji", "speaker": "Rachel", "note": "说话人: Rachel"}, {"l": 414, "lt": "Lesson 114 No Pain, No Gain 一分耕耘，一分收获", "i": 2, "type": "dialog", "en": "He's a salesman.", "zh": "他是个推销员·", "audio": "chuji_l114_02.mp3", "localAudio": "audio_chunks/chuji_l114_02.mp3", "b64": "", "src": "chuji", "speaker": "Derek", "note": "说话人: Derek"}, {"l": 414, "lt": "Lesson 114 No Pain, No Gain 一分耕耘，一分收获", "i": 3, "type": "dialog", "en": "That's a difficult way to make a living.", "zh": "以那种方式谋生是很困难的。", "audio": "chuji_l114_03.mp3", "localAudio": "audio_chunks/chuji_l114_03.mp3", "b64": "", "src": "chuji", "speaker": "Rachel", "note": "说话人: Rachel"}, {"l": 414, "lt": "Lesson 114 No Pain, No Gain 一分耕耘，一分收获", "i": 4, "type": "dialog", "en": "Well, remember: No pain, no gain.", "zh": "嗯；要记住：一分耕耘，一分收获。", "audio": "chuji_l114_04.mp3", "localAudio": "audio_chunks/chuji_l114_04.mp3", "b64": "", "src": "chuji", "speaker": "Derek", "note": "说话人: Derek"}, {"l": 415, "lt": "Lesson 115 Wait and See 静候观望", "i": 1, "type": "reading", "en": "Cliff and Bonnie have known each other for two years.", "zh": "克里夫和邦妮彼此相识已有两年了。", "audio": "chuji_l115_01.mp3", "localAudio": "audio_chunks/chuji_l115_01.mp3", "b64": "", "src": "chuji"}, {"l": 415, "lt": "Lesson 115 Wait and See 静候观望", "i": 2, "type": "reading", "en": "They have talked about getting married since last year.", "zh": "自从去年以来，他们就在讨论结婚的事。", "audio": "chuji_l115_02.mp3", "localAudio": "audio_chunks/chuji_l115_02.mp3", "b64": "", "src": "chuji"}, {"l": 415, "lt": "Lesson 115 Wait and See 静候观望", "i": 3, "type": "reading", "en": "Cliff has already decided that Bonnie is the right girl for him.", "zh": "克里夫已经认定邦妮就是适合他的女孩。", "audio": "chuji_l115_03.mp3", "localAudio": "audio_chunks/chuji_l115_03.mp3", "b64": "", "src": "chuji"}, {"l": 415, "lt": "Lesson 115 Wait and See 静候观望", "i": 4, "type": "reading", "en": "However, Bonnie has not really made up her mind about him yet.", "zh": "然而，邦妮对他尚未打定主意。", "audio": "chuji_l115_04.mp3", "localAudio": "audio_chunks/chuji_l115_04.mp3", "b64": "", "src": "chuji"}, {"l": 415, "lt": "Lesson 115 Wait and See 静候观望", "i": 5, "type": "reading", "en": "She likes Cliff a lot, but she thinks he's not ambitious enough.", "zh": "她很喜欢克里夫，但是她认为他还不够有抱负。", "audio": "chuji_l115_05.mp3", "localAudio": "audio_chunks/chuji_l115_05.mp3", "b64": "", "src": "chuji"}, {"l": 415, "lt": "Lesson 115 Wait and See 静候观望", "i": 6, "type": "reading", "en": "Bonnie knows that getting married is a serious matter, so she's going to wait and see before she makes a final decision.", "zh": "邦妮知道结婚是件严肃的事情，因此在她下最后决定前，她将静候观望。", "audio": "chuji_l115_06.mp3", "localAudio": "audio_chunks/chuji_l115_06.mp3", "b64": "", "src": "chuji"}, {"l": 416, "lt": "Lesson 116 We're Engaged 我们订婚了", "i": 1, "type": "dialog", "en": "How long have you known each other?", "zh": "你们彼此认识已有多久了？", "audio": "chuji_l116_01.mp3", "localAudio": "audio_chunks/chuji_l116_01.mp3", "b64": "", "src": "chuji", "speaker": "Charles", "note": "说话人: Charles"}, {"l": 416, "lt": "Lesson 116 We're Engaged 我们订婚了", "i": 2, "type": "dialog", "en": "We've known each other since we were kids.", "zh": "自从孩提时我们就已认识了。", "audio": "chuji_l116_02.mp3", "localAudio": "audio_chunks/chuji_l116_02.mp3", "b64": "", "src": "chuji", "speaker": "Diana", "note": "说话人: Diana"}, {"l": 416, "lt": "Lesson 116 We're Engaged 我们订婚了", "i": 3, "type": "dialog", "en": "Has he proposed to you yet?", "zh": "他向你求婚了吗？", "audio": "chuji_l116_03.mp3", "localAudio": "audio_chunks/chuji_l116_03.mp3", "b64": "", "src": "chuji", "speaker": "Charies", "note": "说话人: Charies"}, {"l": 416, "lt": "Lesson 116 We're Engaged 我们订婚了", "i": 4, "type": "dialog", "en": "Yes. In fact, we're engaged.", "zh": "是的。事实上，我们订婚了。", "audio": "chuji_l116_04.mp3", "localAudio": "audio_chunks/chuji_l116_04.mp3", "b64": "", "src": "chuji", "speaker": "Diana", "note": "说话人: Diana"}, {"l": 417, "lt": "Lesson 117 Time Flies 光阴似箭", "i": 1, "type": "reading", "en": "Time is precious.", "zh": "时间是很宝贵的。", "audio": "chuji_l117_01.mp3", "localAudio": "audio_chunks/chuji_l117_01.mp3", "b64": "", "src": "chuji"}, {"l": 417, "lt": "Lesson 117 Time Flies 光阴似箭", "i": 2, "type": "reading", "en": "Nobody can afford to waste time.", "zh": "谁都浪费不起时间。", "audio": "chuji_l117_02.mp3", "localAudio": "audio_chunks/chuji_l117_02.mp3", "b64": "", "src": "chuji"}, {"l": 417, "lt": "Lesson 117 Time Flies 光阴似箭", "i": 3, "type": "reading", "en": "Once time has gone by, it will never return.", "zh": "时间一旦消逝，就永不再回来了。", "audio": "chuji_l117_03.mp3", "localAudio": "audio_chunks/chuji_l117_03.mp3", "b64": "", "src": "chuji"}, {"l": 417, "lt": "Lesson 117 Time Flies 光阴似箭", "i": 4, "type": "reading", "en": "You can never turn the clock back.", "zh": "你永远也无法让时光倒流。", "audio": "chuji_l117_04.mp3", "localAudio": "audio_chunks/chuji_l117_04.mp3", "b64": "", "src": "chuji"}, {"l": 417, "lt": "Lesson 117 Time Flies 光阴似箭", "i": 5, "type": "reading", "en": "Time passes very quickly.", "zh": "时间过得很快。", "audio": "chuji_l117_05.mp3", "localAudio": "audio_chunks/chuji_l117_05.mp3", "b64": "", "src": "chuji"}, {"l": 417, "lt": "Lesson 117 Time Flies 光阴似箭", "i": 6, "type": "reading", "en": "In fact, people say time flies.", "zh": "事实上，人们说光阴似箭。", "audio": "chuji_l117_06.mp3", "localAudio": "audio_chunks/chuji_l117_06.mp3", "b64": "", "src": "chuji"}, {"l": 417, "lt": "Lesson 117 Time Flies 光阴似箭", "i": 7, "type": "reading", "en": "Time and tide wait for no man.", "zh": "岁月不待人。", "audio": "chuji_l117_07.mp3", "localAudio": "audio_chunks/chuji_l117_07.mp3", "b64": "", "src": "chuji"}, {"l": 417, "lt": "Lesson 117 Time Flies 光阴似箭", "i": 8, "type": "reading", "en": "We should, therefore, make the best use of our time.", "zh": "因此，我们应该好好利用我们的时间。", "audio": "chuji_l117_08.mp3", "localAudio": "audio_chunks/chuji_l117_08.mp3", "b64": "", "src": "chuji"}, {"l": 418, "lt": "Lesson 118 The Eiffel Tower 艾菲尔铁塔", "i": 1, "type": "dialog", "en": "Have you ever been to Paris?", "zh": "你曾去过巴黎吗？", "audio": "chuji_l118_01.mp3", "localAudio": "audio_chunks/chuji_l118_01.mp3", "b64": "", "src": "chuji", "speaker": "Ivy", "note": "说话人: Ivy"}, {"l": 418, "lt": "Lesson 118 The Eiffel Tower 艾菲尔铁塔", "i": 2, "type": "dialog", "en": "No, I haven't.", "zh": "不，我没去过。", "audio": "chuji_l118_02.mp3", "localAudio": "audio_chunks/chuji_l118_02.mp3", "b64": "", "src": "chuji", "speaker": "Homer", "note": "说话人: Homer"}, {"l": 418, "lt": "Lesson 118 The Eiffel Tower 艾菲尔铁塔", "i": 3, "type": "dialog", "en": "Then you have never seen the Eiffel Tower?", "zh": "那么你从未见过艾菲尔铁塔？", "audio": "chuji_l118_03.mp3", "localAudio": "audio_chunks/chuji_l118_03.mp3", "b64": "", "src": "chuji", "speaker": "Ivy", "note": "说话人: Ivy"}, {"l": 418, "lt": "Lesson 118 The Eiffel Tower 艾菲尔铁塔", "i": 4, "type": "dialog", "en": "No, I haven't.", "zh": "是的，我没见过。", "audio": "chuji_l118_04.mp3", "localAudio": "audio_chunks/chuji_l118_04.mp3", "b64": "", "src": "chuji", "speaker": "Homer", "note": "说话人: Homer"}, {"l": 418, "lt": "Lesson 118 The Eiffel Tower 艾菲尔铁塔", "i": 5, "type": "dialog", "en": "What a pity!", "zh": "真可惜！", "audio": "chuji_l118_05.mp3", "localAudio": "audio_chunks/chuji_l118_05.mp3", "b64": "", "src": "chuji", "speaker": "Ivy", "note": "说话人: Ivy"}, {"l": 419, "lt": "Lesson 119 My Name Isn't Jack 我的名字不是杰克", "i": 1, "type": "reading", "en": "My father has never done anything exciting in his life.", "zh": "我父亲一生中从未做过任何令人兴奋的事情。", "audio": "chuji_l119_01.mp3", "localAudio": "audio_chunks/chuji_l119_01.mp3", "b64": "", "src": "chuji"}, {"l": 419, "lt": "Lesson 119 My Name Isn't Jack 我的名字不是杰克", "i": 2, "type": "reading", "en": "He has never traveled abroad.", "zh": "他从未出国旅行。", "audio": "chuji_l119_02.mp3", "localAudio": "audio_chunks/chuji_l119_02.mp3", "b64": "", "src": "chuji"}, {"l": 419, "lt": "Lesson 119 My Name Isn't Jack 我的名字不是杰克", "i": 3, "type": "reading", "en": "He has never smoked, drunk wine, or gone dancing.", "zh": "他从未抽过烟、喝过酒或跳过舞。", "audio": "chuji_l119_03.mp3", "localAudio": "audio_chunks/chuji_l119_03.mp3", "b64": "", "src": "chuji"}, {"l": 419, "lt": "Lesson 119 My Name Isn't Jack 我的名字不是杰克", "i": 4, "type": "reading", "en": "He has never even gone to a movie.", "zh": "他甚至未曾去看过一场电影。", "audio": "chuji_l119_04.mp3", "localAudio": "audio_chunks/chuji_l119_04.mp3", "b64": "", "src": "chuji"}, {"l": 419, "lt": "Lesson 119 My Name Isn't Jack 我的名字不是杰克", "i": 5, "type": "reading", "en": "One day I asked him, \"Don't you know that all work and no play makes Jack a dull boy?\"", "zh": "有一天我问他：“难道你不知道‘只工作不玩耍，聪明孩子也变傻’吗？”", "audio": "chuji_l119_05.mp3", "localAudio": "audio_chunks/chuji_l119_05.mp3", "b64": "", "src": "chuji"}, {"l": 419, "lt": "Lesson 119 My Name Isn't Jack 我的名字不是杰克", "i": 6, "type": "reading", "en": "He said, \"Well, son, it's a good thing that my name isn't Jack.\"", "zh": "他说：“嗯，儿子，还好我的名字不是杰克。”", "audio": "chuji_l119_06.mp3", "localAudio": "audio_chunks/chuji_l119_06.mp3", "b64": "", "src": "chuji"}, {"l": 420, "lt": "Lesson 120 It's My Treat 由我作东", "i": 1, "type": "dialog", "en": "Have you eaten yet?", "zh": "你吃过了吗？", "audio": "chuji_l120_01.mp3", "localAudio": "audio_chunks/chuji_l120_01.mp3", "b64": "", "src": "chuji", "speaker": "Dale", "note": "说话人: Dale"}, {"l": 420, "lt": "Lesson 120 It's My Treat 由我作东", "i": 2, "type": "dialog", "en": "No.", "zh": "还没。", "audio": "chuji_l120_02.mp3", "localAudio": "audio_chunks/chuji_l120_02.mp3", "b64": "", "src": "chuji", "speaker": "Molly", "note": "说话人: Molly"}, {"l": 420, "lt": "Lesson 120 It's My Treat 由我作东", "i": 3, "type": "dialog", "en": "I haven't, either. Let's have lunch together.", "zh": "我也还没吃·那咱们-一起吃午饭吧。", "audio": "chuji_l120_03.mp3", "localAudio": "audio_chunks/chuji_l120_03.mp3", "b64": "", "src": "chuji", "speaker": "Dale", "note": "说话人: Dale"}, {"l": 420, "lt": "Lesson 120 It's My Treat 由我作东", "i": 4, "type": "dialog", "en": "I didn't bring enough money.", "zh": "我没带够钱。", "audio": "chuji_l120_04.mp3", "localAudio": "audio_chunks/chuji_l120_04.mp3", "b64": "", "src": "chuji", "speaker": "Molly", "note": "说话人: Molly"}, {"l": 420, "lt": "Lesson 120 It's My Treat 由我作东", "i": 5, "type": "dialog", "en": "Don't worry about it. It's my treat.", "zh": "别担心，由我作东。", "audio": "chuji_l120_05.mp3", "localAudio": "audio_chunks/chuji_l120_05.mp3", "b64": "", "src": "chuji", "speaker": "Dale", "note": "说话人: Dale"}, {"l": 420, "lt": "Lesson 120 It's My Treat 由我作东", "i": 6, "type": "dialog", "en": "Thanks!", "zh": "谢谢！", "audio": "chuji_l120_06.mp3", "localAudio": "audio_chunks/chuji_l120_06.mp3", "b64": "", "src": "chuji", "speaker": "Molly", "note": "说话人: Molly"}];